export const friendRequest = catchAsync(async (req, res) => {
  try {
    let actionUserId = req.params.id
    let { isAccept } = req.body
    console.log("----------->>>>actionUserId", actionUserId)
    const userData = await userService.getUserById(actionUserId);
    if (!userData) {
      throw new ApiError(httpStatus.NOT_FOUND, 'user not found');
    }

    const filter = { user: mongoose.Types.ObjectId(req.user._id) };
    const filter1 = { user: mongoose.Types.ObjectId(actionUserId) };

    if (isAccept) {
      let updateData = {
        $push: {
          userFriendList: { friendOfUsers: mongoose.Types.ObjectId(actionUserId) }
        }
      }
      let updateData1 = {
        $push: {
          userFriendList: { friendOfUsers: mongoose.Types.ObjectId(req.user._id) }
        }
      }

      await faceBookService.updateFacebookUser(filter, updateData)
      await faceBookService.updateFacebookUser(filter1, updateData1)

    }

    let updateData = {
      $pull: {
        friendRequestlist: { reqUsers: mongoose.Types.ObjectId(actionUserId) }
      }
    }
    let updateData1 = {
      $pull: {
        sendRequestList: { userSendRequests: mongoose.Types.ObjectId(req.user._id) }
      }
    }

    await faceBookService.updateFacebookUser(filter, updateData)
    await faceBookService.updateFacebookUser(filter1, updateData1)

    res.status(httpStatus.OK).send({
      results: {
        success: true,
      },
    });
  } catch (error) {
    console.error("Error action friend request:", error);
    throw error;
  }

});

export const getFriendRequestWithPagination = catchAsync(async (req, res) => {
  try {
    // paginate api logic
    let {
      start,
      limit,
    } = req.body;

    const pageStart = start ? start : 0;
    const pageLimit = limit ? limit : 10;

    let aggregateQuery = [
      {
        $match: {
          user: mongoose.Types.ObjectId(req.user._id)
        }
      },
      {
        $lookup: {
          from: 'User',
          localField: 'friendRequestlist.reqUsers',
          foreignField: '_id',
          as: 'friendDetails'
        }
      },
      { $unwind: '$friendDetails' },
      {
        $project: {
          'friendDetails.name': 1,
          'user': 1
        }
      }

    ];

    const friendRequestlist = await faceBookService.faceBookUserAggregatePaginate({
      query: aggregateQuery,
      offset: pageStart,
      limit: pageLimit,
    })

    res.status(httpStatus.OK).send({
      results: {
        success: true,
        friendRequestlist,
      },
    });
  } catch (error) {
    console.error("Error fetching Facebook user friend requests:", error);
    throw error;
  }

});
